#!/usr/bin/env python3
"""
Regenerate the "Directory Structure" tree in README.md from `git ls-files`, so the tree never drifts
from what the kit actually ships.

The tree lives between these two markers in README.md:
    <!-- tree:begin (generated by scripts/gen-readme-tree.py, do not edit by hand) -->
    <!-- tree:end -->

Run from the repo root after you add, remove or rename a tracked file:
    python3 scripts/gen-readme-tree.py            # rewrite README.md in place
    python3 scripts/gen-readme-tree.py --check    # exit 1 if README.md is out of date (no write)
    python3 scripts/gen-readme-tree.py --count    # print the tracked-file count (for the docs that quote it)

Only tracked files appear, so untracked scratch files never leak into the tree. Files without an entry
in COMMENTS are listed without a comment; add one here when you add a file worth explaining.
"""
import subprocess
import sys
from pathlib import Path

BEGIN = "<!-- tree:begin (generated by scripts/gen-readme-tree.py, do not edit by hand) -->"
END = "<!-- tree:end -->"

# One-line notes shown next to a path. Keys are repo-relative paths.
